WFJ.Data.add("gossip", {
  ["62086a448a57e4d7"] = { "Ok, eccomi. Vieni a comprare la mia merce finché c'è. Cioè, ti sto dando la precedenza.", "." },
  ["620bf8aad867cc83"] = { "Evvai! Ora se le stanno dando!", "." },
  ["620da812a75eb4ba"] = { "La Fratellanza non si farà ostacolare dagli insetti.", "." },
  ["62139ea3c508379d"] = { "Funzionerà: continua attraverso questo varco. La strada per Un'Goro è dritta a ovest da qui, una volta aggirati questi maledetti insetti.", "." },
  ["62143107f567b6fa"] = { "EHI! Non è giusto!", "." },
  ["621a21e86e470f8e"] = { "Devo sapere una cosa: come facevi ad andare in bagno con quell'affare addosso?", "." },
  ["621e46c8e9c3e0d6"] = { "Ti chiedo scusa, non pensavo che potessi capire quello che dicevo. Cosa ci fai qui fuori?", "." },
  ["622aae0b39157fc3"] = { "Buongiorno, <signore/signora>. Ti stringerei la mano, ma come vedi sono nel bel mezzo di qualcosa. Posso esserti utile?", "." },
  ["622b2d8447c8ae18"] = { "NEFARIAN È STATO UCCISO! Popolo di Orgrimmar, inchinati davanti alla potenza di {name} e dei suoi alleati, poiché hanno inferto allo Stormo dei Draghi Neri un colpo che di certo scuoterà gli Aspetti dal loro torpore! Questa sconfitta si farà sentire dal padre dello Stormo dei Draghi Neri: oggi Alamorte si contorce nel dolore e nell'angoscia!", "." },
  ["622d017012624ab3"] = { "Dov'è l'anziana Alba Lunga?", "." },
  ["623111d893d963de"] = { "Avvisami quando sei <pronto/pronta> ad ascoltare la storia.", "." },
  ["6233ae94213ceea1"] = { "Perché non ci occupiamo di te adesso, Hendel? Lady Proudmoore ti parlerà alla torre.", "." },
  ["623e61c3ee752993"] = { "Così i fragili esseri viventi hanno qualche dente, dopotutto. Prendetevi pure questo posto, per ora. Torneremo, due volte più forti, e le vostre misere forze cadranno!", "." },
  ["6249dd661b788239"] = { "È in buca! È in buca!", "." },
  ["624f1621f9de51db"] = { "Come osi! Oltraggioso! Ti maledico, {class}. Ti maledico con... la morte!", "." },
  ["624f6faba6502f2f"] = { "Di sicuro è solo incompetenza o una svista di qualche operaio.", "." },
  ["625f39dfeff56ded"] = { "Abbiamo un quarto del silithyst necessario! Continuate così!", "." },
  ["626194e5c8b80e6c"] = { "%s dà da mangiare allo scoiattolo un po' del fluido viscoso.", "." },
  ["6265778624012fbf"] = { "Credi di valere abbastanza da imparare da me? Dal grande Snarl? Non sei altro che un misero verme sotto il mio stivale. Però, prendere un sottoposto potrebbe rendermi più attraente agli occhi di Sumi e Tumi. Vediamo che misere abilità possiedi.", "." },
  ["62674408fa689628"] = { "Lascia questo luogo. <La reliquia emette un arco di fiamma incandescente. Hai acquisito un ricordo: un nano ⟦Dark Iron=Ferroscuro⟧ solitario, circondato da sette cadaveri, inginocchiato davanti a un monolito di fiamma.>", "." },
  ["626ef22699b74672"] = { "Non sei <pronto/pronta>. Parla con Betty Quinn, è vicino alle scale laggiù. Torna da me quando avrai raggiunto un'illuminazione superiore.", "." },
  ["627242c9cef00d29"] = { "Se vuoi addestrarti in cucina, ho qualche consiglio e trucchetto da passarti! Oh oh! Mettiti un grembiule e cominciamo!", "." },
  ["6275e22ff6e316b6"] = { "Non abbiamo molti materiali per la ricostruzione. Ne serviranno molti di più prima che Dun Baldar venga riparata.", "." },
  ["62777e7a93fba162"] = { "Ho sentito che a ⟦Thunder Bluff=Picco del Tuono⟧, a nord, c'è un istruttore di estrazione. Prendi la strada che esce dal villaggio e, una volta lì, sali con l'ascensore fino in cima all'altura. Da lì qualsiasi Guardiano del Picco dovrebbe poterti aiutare.", "." },
  ["62798b80d118a53f"] = { "Ascolta, giovane {class}. Senti il richiamo dell'acqua?", "." },
  ["627f6ce41f170dbb"] = { "Finalmente... la... liberazione... forse non è troppo tardi per... No! Mi serve... altro... tempo...", "." },
  ["62807516cd612f26"] = { "Salute, nobile {class}. Umilmente al servizio del ⟦Cenarion Circle=Circolo Cenariano⟧, auguro che benedizioni e abbondanza siano concesse a te e ai tuoi.", "." },
  ["6282dcabfb045a09"] = { "<I due cultisti qui vicino stanno parlando. Potresti scoprire qualcosa se ti nascondi dietro questo armadio a origliare.>", "." },
  ["62837370ace41df1"] = { "Sono <pronto/pronta> ad ascoltare la tua storia, Tirion.", "." },
  ["6287ba5c71c04fb7"] = { "Qui il comandante di squadriglia anziano Vipore, decollo. Pregate per una morte rapida, Lupi Bianchi.", "." },
  ["628c3f8aea2a263b"] = { "Quando Lolo non vuol rovesciare nemmeno un goccio della sua preziosa birra o sporcarsi il vestitino, chiamano me. Eh già. Il vecchio Hansel è il nano che usano per distribuire un pochino di giustizia e un bel po' di dolore.", "." },
  ["628d36225061a32b"] = { "Se aspetti a venire da me, potrebbe non restare più niente!", "." },
  ["628e4e289f9129f7"] = { "Nefarian aveva ordinato che i soggetti inadatti fossero distrutti immediatamente, ma queste bestie miserabili non lo facevano senza prima infliggere una quantità «abbondante» di torture.\n\nQuando eravamo completamente «spezzati», radunavano ciò che restava e ci gettavano a questi bruti. I nostri corpi usati come strumenti nel loro gioco perverso: gettati nella lava o peggio, tra le braccia aperte e in attesa della legione assetata di sangue là sotto.", "." },
  ["62974c4ff2c70279"] = { "Vorrei addestrarmi nell'uso delle armi.", "." },
  ["629ecdd06ca74237"] = { "E buona giornata a te, <coraggioso/coraggiosa> {class}. Lo so che cerchi un buon destriero. Non c'è destriero migliore di un raptor sotto le tue redini, te lo dico io, <fratello/sorella>! Dai un'occhiata a quelli che ho da offrire: allevati dalla razza più feroce che ci sia.", "." },
  ["62a5c01dc1ed1301"] = { "Cerchi ⟦Uthan Stillwater=Uthan Acqua Ferma⟧. Lo troverai a ovest del villaggio, a pescare al ⟦Stonebull Lake=Lago Toro di Pietra⟧.", "." },
  ["62a9bed80ca53671"] = { "Psssst. Ci è appena arrivato un po' di Torcibudella. . . .", "." },
  ["62b260d33f05f42d"] = { "Come il vento delle pianure, qui sei sempre <il/la> <benvenuto/benvenuta>.", "." },
  ["62dcf008dc4e8c75"] = { "Va', {name}, e addomestica la più robusta delle bestie di Elwynn.", "." },
  ["62e6d0f6a45b128e"] = { "<Benvenuto/Benvenuta> alla Banca di Darnassus. Offriamo conti e cassette di sicurezza per gli oggetti di valore. Hai già un conto presso di noi, <signore/signora>?", "." },
  ["62eb639f9efa4d80"] = { "Ti condanno a morte!", "." },
  ["62f32f9e676f8b58"] = { "Il titolo di questo libro è scritto a mano con uno svolazzo: Diario di Maureen Dalson.", "." },
  ["62fb352d55cac0c0"] = { "Ehm, tu uccide re, sì? Vuol dire che tu prende suo posto. Questo fa di te nuovo capo! Lunga vita al re!", "." },
  ["62fdb5974e0acc3b"] = { "World of Warcraft e Coca-Cola (R) hanno unito le forze per offrirti la promozione estiva iCoke-World of Warcraft. Cerca i codici sotto i tappi delle bottiglie di Coca-Cola contrassegnate. Poi torna qui e inserisci il codice per vincere un oggetto virtuale.", "." },
